"""PyTorch references for multi-axis rotary apply kernels."""

import torch


def _rotate_half(x: torch.Tensor) -> torch.Tensor:
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def text_mrope_apply_torch(
    query: torch.Tensor,
    key: torch.Tensor,
    cos: torch.Tensor,
    sin: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply Qwen text M-RoPE on query/key [B, H, S, D]."""

    cos = cos.unsqueeze(1)
    sin = sin.unsqueeze(1)
    rotary_dim = cos.shape[-1]

    q_rot = query[..., :rotary_dim]
    k_rot = key[..., :rotary_dim]
    q_embed = (q_rot * cos) + (_rotate_half(q_rot) * sin)
    k_embed = (k_rot * cos) + (_rotate_half(k_rot) * sin)
    query[..., :rotary_dim].copy_(q_embed)
    key[..., :rotary_dim].copy_(k_embed)
    return query, key


def spatial_rope_apply_torch(
    query: torch.Tensor,
    key: torch.Tensor,
    cos: torch.Tensor,
    sin: torch.Tensor,
    *,
    axis_blocks: int = 1,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply block-wise spatial RoPE over arbitrary leading token dimensions."""

    if key.shape != query.shape:
        raise ValueError(
            f"key must match query shape {tuple(query.shape)}, got {tuple(key.shape)}"
        )
    expected_frequencies = (*query.shape[:-2], query.shape[-1])
    if cos.shape != expected_frequencies or sin.shape != expected_frequencies:
        raise ValueError(
            "cos and sin must match query token dimensions and head size "
            f"{expected_frequencies}, got {tuple(cos.shape)} and {tuple(sin.shape)}"
        )
    if axis_blocks < 1 or query.shape[-1] % (2 * axis_blocks):
        raise ValueError(
            "each axis block must have an even rotary dimension, got "
            f"head_dim={query.shape[-1]}, axis_blocks={axis_blocks}"
        )
    orig_q_dtype = query.dtype
    orig_k_dtype = key.dtype
    q = query.float()
    k = key.float()
    cos = cos.unsqueeze(-2).float()
    sin = sin.unsqueeze(-2).float()
    q_blocks = torch.chunk(q, axis_blocks, dim=-1)
    k_blocks = torch.chunk(k, axis_blocks, dim=-1)
    cos_blocks = torch.chunk(cos, axis_blocks, dim=-1)
    sin_blocks = torch.chunk(sin, axis_blocks, dim=-1)
    q_out = torch.cat(
        [
            (q_part * cos_part) + (_rotate_half(q_part) * sin_part)
            for q_part, cos_part, sin_part in zip(q_blocks, cos_blocks, sin_blocks)
        ],
        dim=-1,
    )
    k_out = torch.cat(
        [
            (k_part * cos_part) + (_rotate_half(k_part) * sin_part)
            for k_part, cos_part, sin_part in zip(k_blocks, cos_blocks, sin_blocks)
        ],
        dim=-1,
    )
    query.copy_(q_out.to(orig_q_dtype))
    key.copy_(k_out.to(orig_k_dtype))
    return query, key


__all__ = ["spatial_rope_apply_torch", "text_mrope_apply_torch"]
